using System;
using UnityEngine;

namespace LittleBuildersWorld.Audio
{
    public enum SfxId
    {
        ButtonTap,
        Pop,
        Snap,
        Whoosh,
        Star,
        Celebration,
        Sparkle,
        Horn,
        Hydraulic,
        SoilDump,
        Scoop,
        Load,
        BedTip,
        Thud,
        Boing,
        Unlock,
        EngineStart
    }

    /// <summary>Clip table for <see cref="AudioManager"/>. Generated by the setup pipeline (all original, synthesised).</summary>
    [CreateAssetMenu(menuName = "Little Builders World/Audio Library", fileName = "AudioLibrary")]
    public sealed class AudioLibrary : ScriptableObject
    {
        [Serializable]
        public struct Entry
        {
            public SfxId id;
            public AudioClip clip;
            [Range(0f, 1f)] public float volume;
        }

        public Entry[] sfx = Array.Empty<Entry>();
        public AudioClip menuMusic;
        public AudioClip townMusic;
        public AudioClip engineLoop;

        public bool TryGet(SfxId id, out Entry entry)
        {
            for (int i = 0; i < sfx.Length; i++)
            {
                if (sfx[i].id == id && sfx[i].clip != null)
                {
                    entry = sfx[i];
                    return true;
                }
            }
            entry = default;
            return false;
        }
    }
}
